local HatBoxMaker = {}
local PRODUCTS = {
    iron_hat_box = { name = "Železna škatla za klobuke", ironCost = 1, woodCost = 4, leatherCost = 2, time = 5, cost = 145, prestige = 3, happiness = 2, description = "Železna škatla za shranjevanje klobukov." },
    bronze_hat_box = { name = "Bronasta škatla za klobuke", bronzeCost = 1, ironCost = 1, woodCost = 4, leatherCost = 2, time = 7, cost = 350, prestige = 5, happiness = 3, description = "Bronasta škatla za klobučarje." },
    silver_hat_box = { name = "Srebrna škatla za klobuke", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 4, leatherCost = 2, time = 11, cost = 850, prestige = 10, happiness = 4, description = "Srebrna škatla za plemiške klobučarje." },
    gilded_hat_box = { name = "Pozlačena škatla za klobuke", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 4, leatherCost = 2, time = 15, cost = 1820, prestige = 19, happiness = 5, description = "Pozlačena škatla za dvorne klobučarje." },
    jewel_set_hat_box = { name = "Draguljasta škatla za klobuke", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 4, leatherCost = 2, time = 19, cost = 3950, prestige = 35, happiness = 7, description = "Draguljasta škatla za kraljeve klobučarje." },
    royal_sovereign_hat_box = { name = "Kraljevski suverena škatla za klobuke", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 5, leatherCost = 2, time = 26, cost = 8500, prestige = 67, happiness = 13, description = "Suverena škatla z biseri za krono." },
}
local BUILDINGS = {
    hatbox_workshop = { name = "Škatlena delavnica", cost = { gold = 305, wood = 195, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    hatbox_house = { name = "Škatlena hiša", cost = { gold = 1135, wood = 380, stone = 260, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_hatbox_atelier = { name = "Mojstrski škatleni atelje", cost = { gold = 2880, wood = 440, stone = 500, silver = 33, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    sovereign_hatbox_palace = { name = "Suverena škatlena palača", cost = { gold = 12480, wood = 680, stone = 805, gold = 80, jewel = 18 }, upkeep = 246, qualityBonus = 55, prestigeBonus = 50 },
}
HatBoxMaker.ironStock = 10; HatBoxMaker.bronzeStock = 8; HatBoxMaker.woodStock = 20; HatBoxMaker.leatherStock = 12; HatBoxMaker.silverStock = 8; HatBoxMaker.goldStock = 6; HatBoxMaker.jewelStock = 4; HatBoxMaker.pearlStock = 4
HatBoxMaker.productStock = {}; HatBoxMaker.buildings = {}; HatBoxMaker.maker = nil; HatBoxMaker.activeMaking = {}; HatBoxMaker.totalProducts = 0; HatBoxMaker.dayTimer = 0
function HatBoxMaker.init() HatBoxMaker.ironStock=10; HatBoxMaker.bronzeStock=8; HatBoxMaker.woodStock=20; HatBoxMaker.leatherStock=12; HatBoxMaker.silverStock=8; HatBoxMaker.goldStock=6; HatBoxMaker.jewelStock=4; HatBoxMaker.pearlStock=4; HatBoxMaker.productStock={}; HatBoxMaker.buildings={}; HatBoxMaker.maker=nil; HatBoxMaker.activeMaking={}; HatBoxMaker.totalProducts=0; HatBoxMaker.dayTimer=0; print("[HatBoxMaker] Royal Hat Box Maker System initialized (6 products, 4 buildings)") end
function HatBoxMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HatBoxMaker.maker={name=n or ("Škatlar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škatlar najet: %s (spretnost: %d)",HatBoxMaker.maker.name,s),"success") end; return true end
function HatBoxMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HatBoxMaker.build(id) local ok,e=HatBoxMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HatBoxMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HatBoxMaker.getQualityBonus() local b=0; for _,bd in ipairs(HatBoxMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HatBoxMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HatBoxMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HatBoxMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HatBoxMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HatBoxMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HatBoxMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HatBoxMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HatBoxMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HatBoxMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HatBoxMaker.buildings==0 then return false,"Potrebna škatlena delavnica" end; if not HatBoxMaker.maker then return false,"Potreben škatlar" end; return true end
function HatBoxMaker.make(pt,qty) qty=qty or 1; local ok,e=HatBoxMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HatBoxMaker.ironStock=HatBoxMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HatBoxMaker.bronzeStock=HatBoxMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HatBoxMaker.woodStock=HatBoxMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HatBoxMaker.leatherStock=HatBoxMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HatBoxMaker.silverStock=HatBoxMaker.silverStock-d.silverCost*qty end; if d.goldCost then HatBoxMaker.goldStock=HatBoxMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HatBoxMaker.jewelStock=HatBoxMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HatBoxMaker.pearlStock=HatBoxMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HatBoxMaker.maker then t=math.max(1,t-math.floor(HatBoxMaker.maker.skill/13)) end; table.insert(HatBoxMaker.activeMaking,{id="hatbox_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HatBoxMaker.completeMaking(m) local q=1.0+(HatBoxMaker.getQualityBonus()/100); if HatBoxMaker.maker then q=q+(HatBoxMaker.maker.skill/140) end; q=math.min(2.5,q); HatBoxMaker.productStock[m.productType]=(HatBoxMaker.productStock[m.productType] or 0)+m.quantity; HatBoxMaker.totalProducts=HatBoxMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HatBoxMaker.maker then HatBoxMaker.maker.itemsMade=HatBoxMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HatBoxMaker.maker.skill=math.min(100,HatBoxMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škatla izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hatbox.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HatBoxMaker.update(dt) if not _G.state then return end; HatBoxMaker.dayTimer=HatBoxMaker.dayTimer+dt; if HatBoxMaker.dayTimer>=30 then HatBoxMaker.dayTimer=0; for i=#HatBoxMaker.activeMaking,1,-1 do local m=HatBoxMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HatBoxMaker.completeMaking(m); table.remove(HatBoxMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HatBoxMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HatBoxMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HatBoxMaker.getStats() return {ironStock=HatBoxMaker.ironStock,bronzeStock=HatBoxMaker.bronzeStock,woodStock=HatBoxMaker.woodStock,leatherStock=HatBoxMaker.leatherStock,silverStock=HatBoxMaker.silverStock,goldStock=HatBoxMaker.goldStock,jewelStock=HatBoxMaker.jewelStock,pearlStock=HatBoxMaker.pearlStock,productStock=HatBoxMaker.productStock,numBuildings=#HatBoxMaker.buildings,hasMaker=HatBoxMaker.maker~=nil,makerName=HatBoxMaker.maker and HatBoxMaker.maker.name or "—",makerSkill=HatBoxMaker.maker and HatBoxMaker.maker.skill or 0,activeMaking=#HatBoxMaker.activeMaking,totalProducts=HatBoxMaker.totalProducts} end
return HatBoxMaker
